    pulseAmt *= 0.945;
    planeBorders[pulseLayer].material.color.copy(BORDER_BASE).lerp(BORDER_HL, pulseAmt);
  } else if (pulseLayer >= 0) {
    planeBorders[pulseLayer].material.color.copy(BORDER_BASE);
    pulseLayer = -1; pulseAmt = 0;
  }
}
figLoop();

updateVisual();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

