// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
   plane fill (×5)       → PlaneGeometry(6,6) rot -90°X, MeshBasic white a=0.30
   plane border (×5)     → 4 flat BoxGeometry ribbons (w 0.085) dark #3b3b3b  (thick, solid)
   plane gridlines (×5)  → 2 flat ribbons (w 0.035) light #d9d9d9 cross
   static points (5×10)  → THREE.Points, disc sprite, tab10 colour, 40 pts, size 4.5
   moving cloud (×10)    → THREE.Points, size 6.5, positions interpolated along trajectory
   connectors (4 gaps×10)→ LineSegments + LineDashedMaterial (dash .15 gap .12) a≤0.75
   legend box fill (×4)  → ShapeGeometry rounded rect 4.4×1.1 r0.35 white
   legend box edge (×4)  → LineLoop rounded-rect outline, black
   legend arrows (×5)    → PlaneGeometry shaft + ShapeGeometry triangle head, black
   legend text (×4)      → addLabel 'ViT block x3', monospace 14px
   plane text (×5)       → addLabel 'embedding' / 'after blocks n-m', 11px grey
────────────────────────────────────────────────────────────────────────── */

const CLASSES = [
  { name: 'olive',  hex: 0xbcbd22, T: [-2.45,  1.05] },
  { name: 'blue',   hex: 0x1f77b4, T: [-2.05,  0.35] },
  { name: 'green',  hex: 0x2ca02c, T: [-1.55, -0.20] },
  { name: 'teal',   hex: 0x17becf, T: [-0.95, -0.70] },
  { name: 'gray',   hex: 0x7f7f7f, T: [ 0.35, -0.95] },
  { name: 'orange', hex: 0xff7f0e, T: [-0.05, -1.30] },
  { name: 'red',    hex: 0xd62728, T: [ 1.05, -1.20] },
  { name: 'brown',  hex: 0x8c564b, T: [ 0.80, -0.95] },
  { name: 'purple', hex: 0x9467bd, T: [ 1.70, -0.85] },
  { name: 'pink',   hex: 0xe377c2, T: [ 2.30, -0.45] },
];
const NPC = 40;                 // points per class  (fine scatter bands)
const LAYER_Y = [0, 3, 6, 9, 12];
const HALF = 3;                 // plane half-size

/* ── deterministic RNG ─────────────────────────────────────────────────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(20240517);
const lerp = (a, b, t) => a + (b - a) * t;
const clamp01 = (v) => Math.min(1, Math.max(0, v));

/* ── build per-point layouts on all 5 planes ───────────────────────────── */
CLASSES.forEach((cls) => {
  const micro = [
    [-2.5 + 5.0 * rnd(), -1.1 + 2.0 * rnd()],
    [-2.5 + 5.0 * rnd(), -1.1 + 2.0 * rnd()],
  ];
  cls.pts = [];
  for (let i = 0; i < NPC; i++) {
    const u = rnd(), v = rnd();
    const mc = micro[i % 2];

    // plane 0: wide narrow band, all classes fully interleaved
    const L0 = [-2.65 + 5.3 * u, -0.55 + 0.95 * v - 0.15];

    // band base used by planes 1..3
    const u2 = clamp01(u + 0.14 * (rnd() - 0.5));
    const v2 = clamp01(v + 0.14 * (rnd() - 0.5));
    const wx = -2.55 + 5.1 * u2, wz = -1.05 + 1.9 * v2;

    const L1 = [lerp(wx, mc[0], 0.12), lerp(wz, mc[1], 0.12)];
    const L2 = [lerp(wx, mc[0], 0.30), lerp(wz, mc[1], 0.30)];

    // plane 3: loose colour lobes pulling toward the final clump
    const L3 = [
      lerp(wx, cls.T[0], 0.58) + 0.30 * (rnd() - 0.5) * 2,
      lerp(wz, cls.T[1], 0.58) + 0.26 * (rnd() - 0.5) * 2,
    ];

    // plane 4: compact single-colour clump
    const ang = rnd() * Math.PI * 2, rad = 0.33 * Math.sqrt(rnd());
    const L4 = [cls.T[0] + Math.cos(ang) * rad, cls.T[1] + Math.sin(ang) * rad * 0.8];

    cls.pts.push({ L: [L0, L1, L2, L3, L4] });
  }
});

/* ── catmull-rom trajectory sampling ───────────────────────────────────── */
function cr(p0, p1, p2, p3, t) {
  const t2 = t * t, t3 = t2 * t;
  return 0.5 * ((2 * p1) + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 + (-p0 + 3 * p1 - 3 * p2 + p3) * t3);
}
const _tmpV = new THREE.Vector3();
function posAt(pt, t, out) {
  const tc = Math.min(4, Math.max(0, t));
  const i = Math.min(3, Math.floor(tc));
  const f = tc - i;
  const L = pt.L;
  const a = L[Math.max(0, i - 1)], b = L[i], c = L[i + 1], dd = L[Math.min(4, i + 2)];
  const x = cr(a[0], b[0], c[0], dd[0], f);
  const z = cr(a[1], b[1], c[1], dd[1], f);
  return (out || _tmpV).set(x, tc * 3, z);
}

/* ── circular sprite texture ───────────────────────────────────────────── */
function discTexture() {
  const s = 64, cv = document.createElement('canvas');
  cv.width = cv.height = s;
  const g = cv.getContext('2d');
  g.beginPath(); g.arc(s / 2, s / 2, s / 2 - 2, 0, Math.PI * 2);
  g.fillStyle = '#fff'; g.fill();
  const tex = new THREE.CanvasTexture(cv);
  tex.needsUpdate = true;
  return tex;
}
const DISC = discTexture();

/* ── planes: fill + THICK dark border ribbons + light grid ─────────────── */
const planeFills = [], borderMats = [], borderGroups = [], gridMats = [];
const BORDER_BASE = new THREE.Color(0x3b3b3b);
const BORDER_HL = new THREE.Color(0xff7f0e);
const BW = 0.085;   // border ribbon width (world units) → reads as a bold stroke
const GW = 0.035;

LAYER_Y.forEach((y) => {
  const fill = new THREE.Mesh(
    new THREE.PlaneGeometry(2 * HALF, 2 * HALF),
    new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.30, depthWrite: false, side: THREE.DoubleSide })
  );
  fill.rotation.x = -Math.PI / 2; fill.position.y = y; fill.renderOrder = 1;
  scene.add(fill); planeFills.push(fill);

  // light grid cross
  const gmat = new THREE.MeshBasicMaterial({ color: 0xd9d9d9, transparent: true, opacity: 1, depthWrite: false, side: THREE.DoubleSide });
  const gGroup = new THREE.Group();
  const gA = new THREE.Mesh(new THREE.BoxGeometry(2 * HALF, 0.004, GW), gmat);
  gA.position.set(0, y + 0.002, 0);
  const gB = new THREE.Mesh(new THREE.BoxGeometry(GW, 0.004, 2 * HALF), gmat);
  gB.position.set(0, y + 0.002, 0);
  gGroup.add(gA, gB); gGroup.renderOrder = 2;
  scene.add(gGroup); gridMats.push(gmat);

  // thick dark border made of 4 flat ribbons
  const bmat = new THREE.MeshBasicMaterial({
    color: BORDER_BASE.clone(), transparent: true, opacity: 1, depthWrite: false, side: THREE.DoubleSide,
  });
  const bg = new THREE.Group();
  const eLen = 2 * HALF + BW;
  const mkX = (zs) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(eLen, 0.006, BW), bmat);
    m.position.set(0, y + 0.004, zs * HALF); return m;
  };
  const mkZ = (xs) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(BW, 0.006, eLen), bmat);
    m.position.set(xs * HALF, y + 0.004, 0); return m;
  };
  bg.add(mkX(-1), mkX(1), mkZ(-1), mkZ(1));
  bg.renderOrder = 7;
  scene.add(bg);
  borderMats.push(bmat); borderGroups.push(bg);
});

/* ── static point clouds (5 layers × 10 classes) ───────────────────────── */
const staticClouds = [];
const pickables = [];
for (let k = 0; k < 5; k++) {
  const row = [];
  CLASSES.forEach((cls, ci) => {
    const arr = new Float32Array(NPC * 3);
    for (let i = 0; i < NPC; i++) {
      const p = cls.pts[i].L[k];
      arr[i * 3] = p[0]; arr[i * 3 + 1] = LAYER_Y[k] + 0.01; arr[i * 3 + 2] = p[1];
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(arr, 3));
    const m = new THREE.PointsMaterial({
      color: cls.hex, size: 4.5, sizeAttenuation: false, map: DISC,
      transparent: true, opacity: 0.95, depthWrite: false, alphaTest: 0.2,
    });
    const pts = new THREE.Points(g, m);
    pts.renderOrder = 6;
    pts.userData.cls = ci;
    scene.add(pts); row.push(pts); pickables.push(pts);
  });
  staticClouds.push(row);
}

/* ── moving cloud (travels with the depth slider) ──────────────────────── */
const movingClouds = [];
CLASSES.forEach((cls, ci) => {
  const arr = new Float32Array(NPC * 3);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(arr, 3));
  const m = new THREE.PointsMaterial({
    color: cls.hex, size: 6.5, sizeAttenuation: false, map: DISC,
    transparent: true, opacity: 1, depthWrite: false, alphaTest: 0.2,
  });
  const pts = new THREE.Points(g, m);
  pts.renderOrder = 8;
  pts.userData.cls = ci;
  scene.add(pts); movingClouds.push(pts); pickables.push(pts);
});

/* ── dashed connectors: 4 gaps × 10 classes ────────────────────────────── */
const connectors = [];
const SUB = 12;
for (let g = 0; g < 4; g++) {
  const row = [];
  CLASSES.forEach((cls) => {
    const pos = [], dist = [];
    const a = new THREE.Vector3(), b = new THREE.Vector3();
    for (let i = 0; i < NPC; i++) {
      posAt(cls.pts[i], g, a);
      let acc = 0;
      for (let s = 1; s <= SUB; s++) {
        posAt(cls.pts[i], g + s / SUB, b);
        pos.push(a.x, a.y, a.z, b.x, b.y, b.z);
        dist.push(acc); acc += a.distanceTo(b); dist.push(acc);
        a.copy(b);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(pos), 3));
    geo.setAttribute('lineDistance', new THREE.BufferAttribute(new Float32Array(dist), 1));
    const mat = new THREE.LineDashedMaterial({
      color: cls.hex, dashSize: 0.15, gapSize: 0.12,
      transparent: true, opacity: 0.75, depthWrite: false,
    });
    const seg = new THREE.LineSegments(geo, mat);
    seg.renderOrder = 3;
    scene.add(seg); row.push(seg);
  });
  connectors.push(row);
}

/* ── legend column (billboarded group) ─────────────────────────────────── */
const legend = new THREE.Group();
legend.position.set(-7.4, 6, 0);
scene.add(legend);

function roundedRect(w, h, r) {
  const s = new THREE.Shape();
  const x = -w / 2, y = -h / 2;
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y); s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r); s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h); s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r); s.quadraticCurveTo(x, y, x + r, y);
  return s;
}

const boxLocalY = [-4.5, -1.5, 1.5, 4.5];   // world Y 1.5, 4.5, 7.5, 10.5
boxLocalY.forEach((ly) => {
  const shape = roundedRect(4.4, 1.1, 0.35);
  const fill = new THREE.Mesh(
    new THREE.ShapeGeometry(shape),
    new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide })
  );
  fill.position.set(0, ly, -0.01);
  legend.add(fill);
  const pts = shape.getPoints(48).map(p => new THREE.Vector3(p.x, p.y + ly, 0));
  const edge = new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x000000 })
  );
  legend.add(edge);
  // thicken the rounded outline slightly with a second, offset loop
  const edge2 = new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints(pts.map(p => p.clone().multiplyScalar(1.0)).map(p => p.clone().add(new THREE.Vector3(0.015, 0, 0)))),
    new THREE.LineBasicMaterial({ color: 0x000000 })
  );
  legend.add(edge2);
});

const arrowLocalY = [-5.7, -3.0, 0.0, 3.0, 6.0];  // world Y 0.3, 3, 6, 9, 12
arrowLocalY.forEach((ly) => {
  const shaftLen = 1.1;
  const shaft = new THREE.Mesh(
    new THREE.PlaneGeometry(0.1, shaftLen),
    new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide })
  );
  shaft.position.set(0, ly - 0.7 + shaftLen / 2, 0);
  legend.add(shaft);
  const tri = new THREE.Shape();
  tri.moveTo(-0.19, 0); tri.lineTo(0.19, 0); tri.lineTo(0, 0.36); tri.lineTo(-0.19, 0);
  const head = new THREE.Mesh(
    new THREE.ShapeGeometry(tri),
    new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide })
  );
  head.position.set(0, ly + 0.36, 0);
  legend.add(head);
});

/* ── camera (orthographic, matching the source's shallow diamond) ──────── */
controls.enablePan = false;
controls.minPolarAngle = THREE.MathUtils.degToRad(12);
controls.maxPolarAngle = THREE.MathUtils.degToRad(86);

const VIEW = { projection: 'orthographic', axisScreenAngles: { x: 22, z: 22 }, heightFraction: 0.86 };
setCameraView(VIEW);
legend.quaternion.copy(camera.quaternion);   // billboard, then re-fit bounds
setCameraView(VIEW);
document.getElementById('btnReset').style.display = '';

/* ── labels ────────────────────────────────────────────────────────────── */
const legendLabels = boxLocalY.map((ly) => {
  const e = addLabel('ViT block x3', new THREE.Vector3(-7.4, ly + 6, 0), { fontSize: '14px' });
  e.div.style.fontFamily = 'ui-monospace, Consolas, monospace';
  e.local = new THREE.Vector3(0, ly, 0.02);
  return e;
});

const planeLabelNames = ['embedding', 'after blocks 1-3', 'after blocks 4-6', 'after blocks 7-9', 'after blocks 10-12'];
const planeLabels = LAYER_Y.map((y, k) =>
  addLabel(planeLabelNames[k], new THREE.Vector3(HALF + 0.1, y, HALF + 0.1),
    { fontSize: '11px', color: '#666', offset: [40, 8], background: 'rgba(255,255,255,0.8)' })
);

/* ── state + visual update ─────────────────────────────────────────────── */
const state = { depth: 4, stage: 4, traj: true, fade: true };
let hovered = null;
let pulseLayer = -1, pulseAmt = 0;

// High floor: even un-reached planes stay clearly readable (source shows all 5).
const fadeFor = (k) => state.fade
  ? 0.45 + 0.55 * clamp01(1 - (k - state.depth))
  : 1;
const gapFade = (g) => state.fade
  ? 0.45 + 0.55 * clamp01(state.depth - g)
  : 1;
const classAlpha = (ci) => (hovered === null ? 1 : (hovered === ci ? 1 : 0.07));

function updateVisual() {
  for (let k = 0; k < 5; k++) {
    const f = fadeFor(k);
    borderMats[k].opacity = f;
    gridMats[k].opacity = 0.85 * f;
    planeFills[k].material.opacity = 0.30 * f;
    CLASSES.forEach((cls, ci) => {
      staticClouds[k][ci].material.opacity = 0.95 * f * classAlpha(ci);
    });
  }
  for (let g = 0; g < 4; g++) {
    const f = gapFade(g);
    CLASSES.forEach((cls, ci) => {
      const m = connectors[g][ci].material;
      m.opacity = 0.78 * f * classAlpha(ci);
      connectors[g][ci].visible = state.traj;
    });
  }
  const v = new THREE.Vector3();
  CLASSES.forEach((cls, ci) => {
    const attr = movingClouds[ci].geometry.attributes.position;
    for (let i = 0; i < NPC; i++) {
      posAt(cls.pts[i], state.depth, v);
      attr.setXYZ(i, v.x, v.y + 0.02, v.z);
    }
    attr.needsUpdate = true;
    movingClouds[ci].geometry.computeBoundingSphere();
    movingClouds[ci].material.opacity = classAlpha(ci);
  });
  planeLabels.forEach((L, k) => {
    L.div.style.opacity = String(state.fade ? (0.45 + 0.55 * clamp01(1 - (k - state.depth))) : 1);
  });
}

/* ── UI wiring ─────────────────────────────────────────────────────────── */
const slider = document.getElementById('depth');
const depthVal = document.getElementById('depthVal');
const stageBtns = Array.from(document.querySelectorAll('#stageBtns button'));
const narrTitle = document.getElementById('narrTitle');
const narrBody = document.getElementById('narrBody');
const hoverInfo = document.getElementById('hoverInfo');

function markStage(s) {
  state.stage = s;
  stageBtns.forEach(b => b.classList.toggle('active', +b.dataset.s === s));
}

slider.addEventListener('input', () => {
  tween = null;
  state.depth = parseFloat(slider.value);
  depthVal.textContent = state.depth.toFixed(2);
  markStage(Math.round(state.depth));
  updateVisual();
});

stageBtns.forEach(b => b.addEventListener('click', () => {
  const s = +b.dataset.s;
  markStage(s);
  pulseLayer = s; pulseAmt = 1;
  startTween(s);
}));

document.getElementById('chkTraj').addEventListener('change', (e) => {
  state.traj = e.target.checked; updateVisual();
});
document.getElementById('chkFade').addEventListener('change', (e) => {
  state.fade = e.target.checked; updateVisual();
});
document.getElementById('chkLegend').addEventListener('change', (e) => {
  legend.visible = e.target.checked;
  legendLabels.forEach(L => { L.div.style.visibility = e.target.checked ? '' : 'hidden'; });
});

/* ── demo steps ────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Patch embeddings', body: 'On the bottom plane every class colour is smeared through one narrow band — the raw patch embeddings carry almost no linear class separation.', depth: 0, stage: 0 },
  { title: 'After 3 ViT blocks', body: 'The first group of three transformer blocks nudges each image along its dashed path; the band thickens but the hues stay heavily intermingled.', depth: 1, stage: 1 },
  { title: 'Midway through the network', body: 'Six and nine blocks in, coherent lobes of a single colour begin to bulge out of the cloud while much of it is still mixed.', depth: 2.5, stage: 2 },
  { title: 'Deep layers pull classes apart', body: 'By the fourth plane the trajectories fan outward and each colour is clearly heading for its own region of the embedding.', depth: 3, stage: 3 },
  { title: 'Final representation', body: 'On the top plane the ten classes sit as compact, single-coloured clumps — the network has untangled the distribution. Hover a clump to trace that class back down.', depth: 4, stage: 4 },
];
let stepIdx = 4, playing = false, playTimer = null;

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  narrTitle.textContent = s.title;
  narrBody.textContent = s.body;
  markStage(s.stage);
  pulseLayer = s.stage; pulseAmt = 1;
  startTween(s.depth);
}
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('btnPlay').addEventListener('click', () => {
  if (playing) { stopPlay(); return; }
  playing = true;
  document.getElementById('btnPlay').textContent = '❚❚ Pause';
  goToStep(0);
  const advance = () => {
    if (!playing) return;
    if (stepIdx >= STEPS.length - 1) { stopPlay(); return; }
    goToStep(stepIdx + 1);
    playTimer = setTimeout(advance, 2400);
  };
  playTimer = setTimeout(advance, 2400);
});
function stopPlay() {
  playing = false; clearTimeout(playTimer);
  document.getElementById('btnPlay').textContent = '▶ Play';
}

/* ── tween ─────────────────────────────────────────────────────────────── */
let tween = null;
function startTween(to) {
  tween = { from: state.depth, to, t0: performance.now(), dur: 950 };
}

/* ── hover: isolate a class ────────────────────────────────────────────── */
const hoverRay = new THREE.Raycaster();
hoverRay.params.Points.threshold = 0.12;
const ptr = new THREE.Vector2();

canvas.addEventListener('pointermove', (e) => {
  const r = canvas.getBoundingClientRect();
  ptr.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ptr.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  hoverRay.setFromCamera(ptr, camera);
  const hits = hoverRay.intersectObjects(pickables, false);
  let c = null;
  for (const h of hits) { if (h.object.material.opacity > 0.15) { c = h.object.userData.cls; break; } }
  if (c !== hovered) {
    hovered = c;
    updateVisual();
    hoverInfo.textContent = c === null
      ? 'Hover any point cloud to isolate one class through the whole stack. Drag to orbit.'
      : 'Class "' + CLASSES[c].name + '" — follow its dashed trajectories from the mixed bottom band up to its own clump on top.';
  }
  if (c !== null) showTooltip('class: ' + CLASSES[c].name, e); else hideTooltip();
});
canvas.addEventListener('pointerleave', () => {
